const useIsStaticRenderer = () => false;
const addPropertyControls = () => {};
const ControlType = {
    Boolean: 'boolean', Number: 'number', String: 'string',
    Color: 'color', Enum: 'enum', Object: 'object',
    Array: 'array', Image: 'image', ResponsiveImage: 'responsiveImage',
    Font: 'font', Transition: 'transition', Link: 'link'
};

import { useEffect, useId, useMemo, useState, type CSSProperties, useRef, type ReactNode } from "react"

// ---------- Runtime (inlined from src/runtime.ts and src/frame.tsx) ----------

// Shared WebGL2 runtime for the material components.
//
// Each material is a small object with init / frame / dispose. The runtime owns everything
// around it, so every material gets the same guarantees:
// - one canvas and one WebGL2 context per component, refused on software rasterisers
//   (the component shows its poster instead);
// - device pixel ratio capped, and the drawing buffer capped in total pixels;
// - frames drawn only while something moves: on demand by default, looping only while the
//   material asks for it, and never while offscreen or in a hidden tab;
// - reduced motion and Framer's editor canvas get still frames: nothing runs on its own,
//   input still redraws;
// - context loss handled; on unmount every listener, observer, frame and GL object is released.
//
// The file has no imports so the bundler can inline it into each single-file Framer component.

type Stage = {
  gl: WebGL2RenderingContext
  canvas: HTMLCanvasElement
  /** Drawing buffer size in device pixels. */
  width: number
  height: number
  /** CSS size of the canvas. */
  cssWidth: number
  cssHeight: number
  dpr: number
  /** True under reduced motion and on Framer's editor canvas: nothing may move on its own. */
  still: boolean
  /** Draw one more frame as soon as possible. */
  invalidate(): void
  /** Ask for continuous frames (while visible) or stop them. */
  setLooping(on: boolean): void
  /** Add a listener that is removed on dispose. */
  listen<K extends keyof HTMLElementEventMap | "visibilitychange" | "webglcontextlost" | "webglcontextrestored">(
    target: HTMLElement | Window | Document,
    type: K,
    fn: (event: K extends keyof HTMLElementEventMap ? HTMLElementEventMap[K] : Event) => void,
    options?: AddEventListenerOptions,
  ): void
  /** Pointer position in 0..1 of the canvas, y down. */
  toLocal(event: PointerEvent | MouseEvent): [number, number]
}

type Material<P> = {
  /** Create GL resources. Called again after a context restore. */
  init(stage: Stage, props: P): void
  /** Props changed: update uniforms or rebuild what depends on them. */
  update?(stage: Stage, props: P, previous: P): void
  resize?(stage: Stage): void
  /** Draw a frame. `time` advances only while frames run. Return true to keep looping. */
  frame(stage: Stage, time: number, dt: number): boolean | void
  /** Release GL resources (the context may already be lost). */
  dispose(stage: Stage): void
  /** Attach input listeners through stage.listen (removed automatically). */
  input?(stage: Stage): void
  /** False while a frame would only show a stand-in (an image still loading): the poster stays up until true. */
  ready?(): boolean
  /** The [vertex, fragment] sources init() compiles, so warmGpu() can compile them off the main thread first. */
  programs?: [string, string][]
}

type MountOptions = {
  maxDpr: number
  /** Cap on drawing-buffer pixels, so a full-bleed canvas on a 5K screen stays affordable. */
  maxPixels?: number
  /** Framer's static renderer (canvas and export): still frames only, and no input. */
  editor?: boolean
  /** Called once, after the first frame reaches the canvas. */
  onFirstFrame?: () => void
  /** Instrumentation for the test bench. */
  stats?: StatsSink
}

type StatsSink = {
  name: string
  onFrame(cpuMs: number, gpuMs: number | null): void
}

type MountResult = {
  /** "gl" while the scene draws; "poster" when WebGL2 is missing, software-only or failed. */
  status: "gl" | "poster"
  setProps(props: unknown): void
  destroy(): void
}

// Counters the cleanup test reads: they must return to zero after unmount.
type Live = { contexts: number; listeners: number; frames: number; observers: number }

const live: Live = ((globalThis as { __materialsLive?: Live }).__materialsLive ??= {
  contexts: 0,
  listeners: 0,
  frames: 0,
  observers: 0,
})

const SOFTWARE = /swiftshader|llvmpipe|softpipe|software|basic render|mesa offscreen/i

function createContext(canvas: HTMLCanvasElement): WebGL2RenderingContext | null {
  const gl = canvas.getContext("webgl2", {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: "default",
    // A software rasteriser draws these scenes at a few frames a second: refuse it and show the poster.
    failIfMajorPerformanceCaveat: true,
    preserveDrawingBuffer: false,
  })
  if (!gl) return null
  const renderer = String(gl.getParameter(gl.RENDERER) ?? "")
  const debug = gl.getExtension("WEBGL_debug_renderer_info")
  const unmasked = debug ? String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL) ?? "") : ""
  if (SOFTWARE.test(renderer) || SOFTWARE.test(unmasked)) {
    gl.getExtension("WEBGL_lose_context")?.loseContext()
    return null
  }
  return gl
}

function mountMaterial<P>(
  host: HTMLElement,
  material: Material<P>,
  initialProps: P,
  options: MountOptions,
): MountResult {
  const canvas = document.createElement("canvas")
  canvas.style.cssText = "position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none"
  canvas.setAttribute("aria-hidden", "true")

  let gl: WebGL2RenderingContext | null = null
  try {
    gl = createContext(canvas)
  } catch {
    gl = null
  }
  if (!gl) {
    return { status: "poster", setProps() {}, destroy() {} }
  }
  host.appendChild(canvas)
  live.contexts++

  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)")
  let props = initialProps
  let raf = 0
  let looping = false
  let dirty = true
  let onScreen = false
  let pageVisible = document.visibilityState === "visible"
  let lost = false
  let destroyed = false
  let time = 0
  let last = 0
  let drawn = false
  const removers: Array<() => void> = []

  const listen: Stage["listen"] = (target, type, fn, opts) => {
    target.addEventListener(type, fn as EventListener, opts)
    live.listeners++
    removers.push(() => {
      target.removeEventListener(type, fn as EventListener, opts)
      live.listeners--
    })
  }

  const stage: Stage = {
    gl,
    canvas,
    width: 1,
    height: 1,
    cssWidth: 1,
    cssHeight: 1,
    dpr: 1,
    still: reduce.matches || !!options.editor,
    invalidate() {
      dirty = true
      schedule()
    },
    setLooping(on) {
      if (looping === on) return
      looping = on
      if (on) schedule()
    },
    listen,
    toLocal(event) {
      const r = canvas.getBoundingClientRect()
      return [(event.clientX - r.left) / Math.max(1, r.width), (event.clientY - r.top) / Math.max(1, r.height)]
    },
  }

  // GPU timing for the test bench only.
  const timer = options.stats ? gl.getExtension("EXT_disjoint_timer_query_webgl2") : null
  const pending: WebGLQuery[] = []

  function readTimers(): number | null {
    if (!timer || !gl) return null
    let result: number | null = null
    while (pending.length) {
      const q = pending[0]
      if (!gl.getQueryParameter(q, gl.QUERY_RESULT_AVAILABLE)) break
      const disjoint = gl.getParameter(timer.GPU_DISJOINT_EXT)
      const ns = gl.getQueryParameter(q, gl.QUERY_RESULT) as number
      gl.deleteQuery(q)
      pending.shift()
      if (!disjoint) result = ns / 1e6
    }
    return result
  }

  function resize(): boolean {
    const rect = host.getBoundingClientRect()
    const cssW = Math.max(1, rect.width)
    const cssH = Math.max(1, rect.height)
    let dpr = Math.min(window.devicePixelRatio || 1, options.maxDpr)
    const maxPixels = options.maxPixels ?? 2_400_000
    if (cssW * cssH * dpr * dpr > maxPixels) dpr = Math.sqrt(maxPixels / (cssW * cssH))
    const w = Math.max(1, Math.round(cssW * dpr))
    const h = Math.max(1, Math.round(cssH * dpr))
    stage.cssWidth = cssW
    stage.cssHeight = cssH
    if (w === stage.width && h === stage.height && dpr === stage.dpr) return false
    stage.width = w
    stage.height = h
    stage.dpr = dpr
    canvas.width = w
    canvas.height = h
    return true
  }

  function canRun() {
    return !destroyed && !lost && onScreen && pageVisible
  }

  function schedule() {
    if (raf || !canRun()) return
    if (!dirty && !(looping && !stage.still)) return
    raf = requestAnimationFrame(tick)
    live.frames++
  }

  function tick(now: number) {
    raf = 0
    live.frames--
    if (!canRun() || !gl) return
    const dt = last ? Math.min(0.05, (now - last) / 1000) : 1 / 60
    last = now
    const moving = looping && !stage.still
    if (moving) time += dt
    dirty = false

    const t0 = performance.now()
    let query: WebGLQuery | null = null
    if (timer && pending.length < 4) {
      query = gl.createQuery()
      if (query) gl.beginQuery(timer.TIME_ELAPSED_EXT, query)
    }
    const keep = material.frame(stage, time, moving ? dt : 0)
    if (query) {
      gl.endQuery(timer!.TIME_ELAPSED_EXT)
      pending.push(query)
    }
    const cpu = performance.now() - t0
    options.stats?.onFrame(cpu, readTimers())
    if (!drawn && (material.ready?.() ?? true)) {
      drawn = true
      options.onFirstFrame?.()
    }

    if (keep === false) looping = false
    else if (keep === true) looping = true
    if (!looping) last = 0
    schedule()
  }

  function start() {
    resize()
    material.init(stage, props)
    material.resize?.(stage)
    stage.invalidate()
  }

  // Size
  const ro = new ResizeObserver(() => {
    if (lost) return
    if (resize()) material.resize?.(stage)
    stage.invalidate()
  })
  ro.observe(host)
  live.observers++

  // Offscreen pause
  const io = new IntersectionObserver(
    (entries) => {
      const entry = entries[entries.length - 1]
      onScreen = entry.isIntersecting
      // Redraw on entering: the buffer may have been cleared or resized while hidden.
      if (onScreen) stage.invalidate()
      else last = 0
    },
    { rootMargin: "64px" },
  )
  io.observe(host)
  live.observers++

  listen(document, "visibilitychange", () => {
    pageVisible = document.visibilityState === "visible"
    last = 0
    if (pageVisible) schedule()
  })

  const onReduce = () => {
    stage.still = reduce.matches || !!options.editor
    stage.invalidate()
  }
  reduce.addEventListener("change", onReduce)
  live.listeners++
  removers.push(() => {
    reduce.removeEventListener("change", onReduce)
    live.listeners--
  })

  listen(canvas, "webglcontextlost", (event) => {
    event.preventDefault()
    lost = true
    if (raf) {
      cancelAnimationFrame(raf)
      raf = 0
      live.frames--
    }
  })
  listen(canvas, "webglcontextrestored", () => {
    lost = false
    pending.length = 0
    stage.width = stage.height = 1
    start()
  })

  start()
  if (!options.editor) material.input?.(stage)

  return {
    status: "gl",
    setProps(next) {
      const previous = props
      props = next as P
      if (!lost) material.update?.(stage, props, previous)
      stage.invalidate()
    },
    destroy() {
      if (destroyed) return
      destroyed = true
      if (raf) {
        cancelAnimationFrame(raf)
        raf = 0
        live.frames--
      }
      ro.disconnect()
      io.disconnect()
      live.observers -= 2
      for (const remove of removers.splice(0)) remove()
      if (gl && !gl.isContextLost()) {
        for (const q of pending) gl.deleteQuery(q)
        material.dispose(stage)
        gl.getExtension("WEBGL_lose_context")?.loseContext()
      }
      pending.length = 0
      canvas.remove()
      live.contexts--
    },
  }
}

// ---------- GL helpers ----------
const FULLSCREEN_VS = `#version 300 es
out vec2 vUv;
void main() {
  // One triangle that covers the viewport.
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  vUv = p;
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`

type Program = {
  program: WebGLProgram
  uniforms: Record<string, WebGLUniformLocation | null>
  use(): void
  dispose(): void
}

function createProgram(gl: WebGL2RenderingContext, vs: string, fs: string): Program {
  const compile = (type: number, source: string) => {
    const shader = gl.createShader(type)!
    gl.shaderSource(shader, source)
    gl.compileShader(shader)
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS) && !gl.isContextLost()) {
      const log = gl.getShaderInfoLog(shader)
      gl.deleteShader(shader)
      throw new Error(`Shader compile failed: ${log}`)
    }
    return shader
  }
  const v = compile(gl.VERTEX_SHADER, vs)
  const f = compile(gl.FRAGMENT_SHADER, fs)
  const program = gl.createProgram()!
  gl.attachShader(program, v)
  gl.attachShader(program, f)
  gl.linkProgram(program)
  gl.deleteShader(v)
  gl.deleteShader(f)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS) && !gl.isContextLost()) {
    throw new Error(`Program link failed: ${gl.getProgramInfoLog(program)}`)
  }
  const uniforms: Program["uniforms"] = {}
  const count = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS) as number
  for (let i = 0; i < count; i++) {
    const info = gl.getActiveUniform(program, i)
    if (!info) continue
    const name = info.name.replace(/\[0\]$/, "")
    uniforms[name] = gl.getUniformLocation(program, info.name)
  }
  return {
    program,
    uniforms,
    use: () => gl.useProgram(program),
    dispose: () => gl.deleteProgram(program),
  }
}

/** Parse a CSS colour (any format the browser accepts) into linear-light RGB. */
function linearRGB(color: string): [number, number, number] {
  const ctx = colorContext()
  ctx.fillStyle = "#000"
  ctx.fillStyle = color
  ctx.clearRect(0, 0, 1, 1)
  ctx.fillRect(0, 0, 1, 1)
  const [r, g, b] = ctx.getImageData(0, 0, 1, 1).data
  const lin = (c: number) => {
    const s = c / 255
    return s <= 0.04045 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4)
  }
  return [lin(r), lin(g), lin(b)]
}

let colorCtx: CanvasRenderingContext2D | null = null

function colorContext() {
  if (!colorCtx) {
    const c = document.createElement("canvas")
    c.width = c.height = 1
    colorCtx = c.getContext("2d", { willReadFrequently: true })!
  }
  return colorCtx
}

/** GLSL: linear to sRGB for the final write, and a small hash for grain. */
const GLSL_COMMON = `
vec3 toLinear(vec3 c) {
  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c));
}
vec3 toSRGB(vec3 c) {
  c = max(c, 0.0);
  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
}
float hash12(vec2 p) {
  vec3 p3 = fract(vec3(p.xyx) * 0.1031);
  p3 += dot(p3, p3.yzx + 33.33);
  return fract((p3.x + p3.y) * p3.z);
}
float vnoise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash12(i), hash12(i + vec2(1, 0)), u.x), mix(hash12(i + vec2(0, 1)), hash12(i + vec2(1, 1)), u.x), u.y);
}
float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int i = 0; i < 5; i++) { s += a * vnoise(p); p = p * 2.03 + 17.1; a *= 0.5; }
  return s;
}
float dither(vec2 frag) { return (hash12(frag) - 0.5) / 255.0; }
`

// Ordered dither so gradients never band on 8-bit output.
const warming = new Map<string, Promise<void>>()

/**
 * Wake the GPU process off the main thread. A worker opens a WebGL2 context on an OffscreenCanvas,
 * compiles and links the given programs, and drops the context. The browser's first context and a
 * cold compile cost 35–60 ms on the main thread in one task; the GPU process caches programs by
 * source, so the page's own compile afterwards finds them ready. Inline source, no network; resolves
 * after 1.5 s at the latest, and at once where workers or OffscreenCanvas are missing.
 */
function warmGpu(programs: [string, string][] = []): Promise<void> {
  const key = programs.map(([v, f]) => v.length + ":" + f.length + ":" + f.slice(-64)).join("|")
  const known = warming.get(key)
  if (known) return known
  if (typeof Worker === "undefined" || typeof OffscreenCanvas === "undefined") return Promise.resolve()
  const done = new Promise<void>((resolve) => {
    let finish = () => resolve()
    const timer = setTimeout(() => finish(), 1500)
    try {
      const src = `onmessage=(e)=>{try{const g=new OffscreenCanvas(1,1).getContext('webgl2');if(g){for(const[v,f]of e.data){const p=g.createProgram();for(const[t,s]of[[g.VERTEX_SHADER,v],[g.FRAGMENT_SHADER,f]]){const h=g.createShader(t);g.shaderSource(h,s);g.compileShader(h);g.attachShader(p,h)}g.linkProgram(p);g.getProgramParameter(p,g.LINK_STATUS)}g.getExtension('WEBGL_lose_context')?.loseContext()}}catch(e){}postMessage(0)}`
      const url = URL.createObjectURL(new Blob([src], { type: "text/javascript" }))
      const worker = new Worker(url)
      finish = () => {
        clearTimeout(timer)
        worker.terminate()
        URL.revokeObjectURL(url)
        resolve()
      }
      worker.onmessage = () => finish()
      worker.onerror = () => finish()
      worker.postMessage(programs)
    } catch {
      finish()
    }
  })
  warming.set(key, done)
  return done
}


type Stats = Record<string, { frames: number; cpu: number[]; gpu: number[] }>

/** The test bench sets window.__materialsStats = {} to collect frame timings. */
function statsSink(name: string): StatsSink | undefined {
  const bag = (globalThis as { __materialsStats?: Stats }).__materialsStats
  if (!bag) return undefined
  const entry = (bag[name] ??= { frames: 0, cpu: [], gpu: [] })
  return {
    name,
    onFrame(cpu, gpu) {
      entry.frames++
      entry.cpu.push(cpu)
      if (gpu !== null) entry.gpu.push(gpu)
      if (entry.cpu.length > 600) entry.cpu.shift()
      if (entry.gpu.length > 600) entry.gpu.shift()
    },
  }
}

type MaterialFrameProps<P> = {
  name: string
  create: () => Material<P>
  props: P
  /** Accessible description of what the scene shows. */
  label: string
  maxDpr: number
  editor: boolean
  poster: ReactNode
  style?: CSSProperties
  /** Keyboard-operable scenes take focus and show a 2px ring. */
  focusable?: boolean
  children?: ReactNode
}

/**
 * Hosts one material. Renders the poster until WebGL is confirmed, and keeps it when WebGL2
 * is missing or software-only. The canvas sits under any children (captions, controls).
 */
function MaterialFrame<P>({ name, create, props, label, maxDpr, editor, poster, style, focusable, children }: MaterialFrameProps<P>) {
  const host = useRef<HTMLDivElement>(null)
  const mounted = useRef<MountResult | null>(null)
  const [status, setStatus] = useState<"pending" | "gl" | "poster">("pending")
  const [ring, setRing] = useState(false)
  const latest = useRef(props)
  latest.current = props

  // Mount once per DPR cap / renderer change; props flow in through setProps. A plain effect, not a
  // layout effect: the page is rendered on the server too, and the poster is what it sends.
  useEffect(() => {
    const el = host.current
    if (!el) return
    let result: MountResult | null = null
    let alive = true
    setStatus("pending")
    // Set up a step at a time, each its own task under 50 ms: an idle task starts the GPU warm-up in a
    // worker, and a later idle task mounts the scene, whose context and compile then find the GPU ready.
    // The poster shows meanwhile.
    const ric = typeof requestIdleCallback === "function" ? requestIdleCallback : null
    const later = (fn: () => void) => (ric ? ric(fn, { timeout: 600 }) : (setTimeout(fn, 0) as unknown as number))
    const cancel = (id: number) => (ric ? cancelIdleCallback(id) : clearTimeout(id))
    const material = create()
    const mount = () => {
      if (!alive) return
      try {
        result = mountMaterial(el, material, latest.current, {
          maxDpr,
          editor,
          stats: statsSink(name),
          // The poster stays up until the scene has drawn, so there is never a blank frame between them.
          onFirstFrame: () => alive && setStatus("gl"),
        })
      } catch (error) {
        console.warn(`[${name}]`, error)
        setStatus("poster")
        return
      }
      mounted.current = result
      if (result.status === "poster") setStatus("poster")
    }
    let step = later(() => {
      if (!alive) return
      warmGpu(material.programs).then(() => {
        if (alive) step = later(mount)
      })
    })
    return () => {
      alive = false
      cancel(step)
      result?.destroy()
      mounted.current = null
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [maxDpr, editor])

  useEffect(() => {
    mounted.current?.setProps(props)
  }, [props])

  return (
    <div
      ref={host}
      role="img"
      aria-label={label}
      data-material={name}
      data-status={status}
      tabIndex={focusable && !editor && status === "gl" ? 0 : undefined}
      onFocus={(e) => setRing(e.currentTarget.matches(":focus-visible"))}
      onBlur={() => setRing(false)}
      style={{
        position: "relative",
        overflow: "hidden",
        width: "100%",
        height: "100%",
        outline: ring ? "2px solid #1f6feb" : "none",
        outlineOffset: 2,
        ...style,
      }}
    >
      {status !== "gl" && <div style={{ position: "absolute", inset: 0 }}>{poster}</div>}
      {children}
    </div>
  )
}

// ---------- RakingLight ----------

/**
 * Raking Light — letters pressed into cotton paper, lit by a lamp held almost flat to the sheet.
 * The relief is a height field: shading from its slope, shadows ray-marched toward the lamp,
 * and the paper's own fibres catching the light. Drag across the sheet (or use the arrow keys)
 * to move the lamp around and up or down.
 *
 * @framerSupportedLayoutWidth any
 * @framerSupportedLayoutHeight any
 * @framerIntrinsicWidth 640
 * @framerIntrinsicHeight 400
 */
export default function RakingLight(props: RakingProps) {
  const p = { ...rakingDefaults, ...props }
  const editor = useIsStaticRenderer()
  // The poster sets the letters on the browser's own measure of the face, once it has loaded (the server
  // render, which can't measure, gets an estimate). A swap to the scene then moves no letter.
  const [fit, setFit] = useState<Fit | null>(null)
  useEffect(() => {
    let live = true
    const measure = () => live && setFit(measureFit(p.text, p.weight, p.font))
    const load = document.fonts?.load?.(`${p.weight} 100px ${p.font}`, p.text)
    load ? load.then(measure, measure) : measure()
    return () => {
      live = false
    }
  }, [p.text, p.weight, p.font])
  const state = useMemo<RakingState>(
    () => ({
      text: p.text,
      font: p.font,
      weight: p.weight,
      mode: p.mode,
      depth: p.depth,
      softness: p.softness,
      azimuth: p.azimuth,
      elevation: p.elevation,
      paper: p.paper,
      inked: p.inked,
      ink: p.ink,
      grain: p.grain,
      interactive: p.interactive,
    }),
    [p.text, p.font, p.weight, p.mode, p.depth, p.softness, p.azimuth, p.elevation, p.paper, p.inked, p.ink, p.grain, p.interactive],
  )
  return (
    <MaterialFrame
      name="raking"
      create={createRaking}
      props={state}
      label={p.label}
      maxDpr={p.maxDpr}
      editor={editor}
      focusable={p.interactive}
      style={{ background: p.paper, ...p.style }}
      poster={<RakingPoster s={state} fit={fit ?? guessFit(state.text)} />}
    />
  )
}

type RakingProps = Partial<typeof rakingDefaults> & { style?: React.CSSProperties }

const rakingDefaults = {
  text: "Raking",
  font: 'ui-serif, "Iowan Old Style", Georgia, serif',
  weight: 600,
  mode: "deboss" as const,
  depth: 0.6,
  softness: 0.35,
  azimuth: 200,
  elevation: 16,
  paper: "#efebe2",
  inked: false,
  ink: "#1d1f22",
  grain: 0.55,
  interactive: true,
  maxDpr: 2,
  label: "Letters pressed into paper, lit by a low lamp. Drag, or use the arrow keys, to move the light.",
}

type RakingState = Omit<typeof rakingDefaults, "maxDpr" | "label">

/** Advance width in em, and how far the alphabetic baseline sits below canvas "middle", in em. */
type Fit = { em: number; base: number }
function measureFit(text: string, weight: number, font: string): Fit | null {
  const g = document.createElement("canvas").getContext("2d")
  if (!g) return null
  g.font = `${weight} 1000px ${font}`
  g.textBaseline = "middle"
  const m = g.measureText(text.trim() || " ")
  return { em: m.width / 1000, base: -(m.alphabeticBaseline ?? -300) / 1000 }
}
const guessFit = (text: string): Fit => ({ em: Math.max(0.6, (text.trim() || " ").length * 0.55), base: 0.3 })

/**
 * The poster, for browsers without a GPU to draw the scene (and the server render): the same letters
 * set exactly as the scene sets them (62% of the height, or 84% of the width when the text is wider,
 * on the measured baseline, 0.04em low), pressed in by two inner edges that follow the lamp: the wall
 * nearest the lamp throws a soft shadow into the letter, and the far wall catches a line of light.
 */
function RakingPoster({ s, fit }: { s: RakingState; fit: Fit }) {
  const id = "raking-" + useId().replace(/[^\w-]/g, "")
  const a = (s.azimuth * Math.PI) / 180
  // Away from the lamp on screen (y down).
  const ax = -Math.cos(a)
  const ay = Math.sin(a)
  const text = s.text.trim() || " "
  const size = `min(62cqh, ${(84 / fit.em).toFixed(3)}cqw)`
  // The filter works in fractions of the text's box: about fit.em wide and 1.2em tall.
  const fx = (em: number) => (em / fit.em).toFixed(5)
  const fy = (em: number) => (em / 1.2).toFixed(5)
  const edge = (k: number, blur: number, colour: string, opacity: number, name: string) => (
    <>
      <feOffset in="SourceAlpha" dx={fx(ax * k)} dy={fy(ay * k)} result={`${name}-o`} />
      <feComposite in="SourceAlpha" in2={`${name}-o`} operator="out" result={`${name}-e`} />
      <feGaussianBlur in={`${name}-e`} stdDeviation={`${fx(blur)} ${fy(blur)}`} result={`${name}-b`} />
      <feFlood floodColor={colour} floodOpacity={opacity} />
      <feComposite in2={`${name}-b`} operator="in" />
      <feComposite in2="SourceAlpha" operator="in" result={name} />
    </>
  )
  return (
    <div aria-hidden="true" style={{ position: "absolute", inset: 0, background: s.paper, overflow: "hidden", containerType: "size" } as CSSProperties}>
      <svg width="100%" height="100%" style={{ display: "block", overflow: "visible", font: `${s.weight} ${size} ${s.font}` }}>
        <defs>
          <filter id={id} x="-5%" y="-10%" width="110%" height="120%" primitiveUnits="objectBoundingBox" colorInterpolationFilters="sRGB">
            {edge(0.026, 0.009, "#000", 0.3, "shade")}
            {edge(-0.01, 0.008, "#fff", 0.4, "light")}
            <feMerge>
              <feMergeNode in="SourceGraphic" />
              <feMergeNode in="shade" />
              <feMergeNode in="light" />
            </feMerge>
          </filter>
        </defs>
        <text x="50%" y="50%" dy={`${(0.04 + fit.base).toFixed(4)}em`} textAnchor="middle" dominantBaseline="alphabetic" fill={s.inked ? s.ink : s.paper} filter={`url(#${id})`}>
          {text}
        </text>
      </svg>
    </div>
  )
}

/** Render the text as a soft white-on-black height map, fitted to the sheet. */
function drawHeight(s: RakingState, width: number, height: number): HTMLCanvasElement {
  const c = document.createElement("canvas")
  c.width = width
  c.height = height
  const g = c.getContext("2d")!
  g.fillStyle = "#000"
  g.fillRect(0, 0, width, height)
  const text = s.text.trim() || " "
  let size = height * 0.62
  g.font = `${s.weight} ${size}px ${s.font}`
  const measured = g.measureText(text).width
  if (measured > width * 0.84) size *= (width * 0.84) / measured
  g.font = `${s.weight} ${size}px ${s.font}`
  g.textAlign = "center"
  g.textBaseline = "middle"
  // One pass. A plate pressed into cotton leaves a flat floor and a short, steep wall, so the blur
  // only rounds the wall: it is about 1.5% of the letter at the default softness. (A wide blur, or a
  // second sharper pass on top, turns the stroke into a pillow with a ridge round it: the bevel look.)
  const blur = Math.max(0.6, s.softness * size * 0.016)
  g.filter = `blur(${blur}px)`
  g.fillStyle = "#fff"
  g.fillText(text, width / 2, height / 2 + size * 0.04)
  return c
}

const FS = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 outColor;
uniform sampler2D uHeight;
uniform vec2 uRes;
uniform vec3 uLight;     // direction toward the lamp
uniform float uDepth;    // negative: pressed into the paper
uniform float uGrain;
uniform vec3 uPaper;
uniform vec3 uInk;
uniform float uInked;
${GLSL_COMMON}

float aspect() { return uRes.x / uRes.y; }

// Paper: mould-made cotton has no grain direction. Short fibres lie every way, over a soft cloud
// where the pulp settled thicker or thinner. (Fibres stretched along x read as brushed metal.)
float strand(vec2 q, float a) {
  vec2 r = mat2(cos(a), -sin(a), sin(a), cos(a)) * q;
  return vnoise(vec2(r.x * 0.35, r.y * 2.2));
}
float cloudAt(vec2 p) { return fbm(p * vec2(aspect(), 1.0) * 7.0); }
// The tooth that tilts the normal. The cloud (cloudAt, 20× wider) barely tilts it over one texel,
// so the slope skips it: four fbm calls a pixel cost the frame budget for no visible change.
float fibres(vec2 p) {
  vec2 q = p * vec2(aspect(), 1.0) * 140.0;
  float strands = (strand(q, 0.3) + strand(q + 17.0, 1.35) + strand(q + 41.0, 2.4)) / 3.0;
  float fine = vnoise(q * 1.7);
  return strands * 0.73 + fine * 0.27;
}

float letter(vec2 uv) { return texture(uHeight, uv).r; }
// The shadow caster is read as a cone: each march sample takes the mip level as wide as its step,
// so no wall is ever narrower than the step that crosses it (a narrower wall is either hit or
// missed whole, and the shadow's edge turns into teeth).
float caster(vec2 uv, float lod) { return textureLod(uHeight, uv, lod).r; }

// The plate crushes the fibres flat: the floor keeps a little of the tooth, the sheet all of it.
float tooth(vec2 uv) { return 1.0 - 0.65 * smoothstep(0.6, 0.95, letter(uv)); }

void main() {
  vec2 uv = vUv;
  vec2 texel = 1.0 / uRes;
  // The letter's slope from a 3-texel span: the 8-bit height map terraces at one texel and the
  // terraces read as scratches on the walls. The fibres keep their own one-texel slope.
  vec2 lt = 1.5 / vec2(textureSize(uHeight, 0));
  float lx = (letter(uv + vec2(lt.x, 0.0)) - letter(uv - vec2(lt.x, 0.0))) * uDepth / (2.0 * lt.y);
  float ly = (letter(uv + vec2(0.0, lt.y)) - letter(uv - vec2(0.0, lt.y))) * uDepth / (2.0 * lt.y);
  float tk = tooth(uv);
  float fx = (fibres(uv + vec2(texel.x, 0.0)) - fibres(uv - vec2(texel.x, 0.0))) * 0.0066 * uGrain * tk / (2.0 * texel.y);
  float fy = (fibres(uv + vec2(0.0, texel.y)) - fibres(uv - vec2(0.0, texel.y))) * 0.0066 * uGrain * tk / (2.0 * texel.y);
  vec3 n = normalize(vec3(-(lx + fx), -(ly + fy), 1.0) * vec3(0.06, 0.06, 1.0));

  vec3 L = normalize(uLight);
  float diffuse = max(dot(n, L), 0.0);
  float flat0 = max(L.z, 1e-3);

  // March toward the lamp over the letter alone (fibres are far too small to cast shadows; letting
  // them in broke every shadow edge into streaks). The lamp has a size, so the penumbra widens with
  // distance from the occluder: hard at the wall's foot, soft further out, and no step pattern.
  vec2 dir = normalize(L.xy + 1e-6) * vec2(1.0 / aspect(), 1.0);
  float rise = L.z / max(length(L.xy), 1e-3) * 0.96;
  float texels = float(textureSize(uHeight, 0).y);
  float h0 = caster(uv, 1.0) * uDepth;
  float top = max(uDepth, 0.0);
  float shadow = 1.0;
  // Steps grow geometrically, t(x) = a((1 + r)^x - 1) / r. Each pixel samples at x = i + j, with j
  // from interleaved gradient noise, so the samples of neighbouring pixels interleave.
  float j = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  float g = pow(1.07, j);
  for (int i = 0; i < 40; i++) {
    float t = 0.0012 * (g - 1.0) / 0.07 + 0.0004;
    float lod = max(1.0, log2(0.0012 * 0.967 * g * texels));
    g *= 1.07;
    float above = h0 + t * rise - caster(uv + dir * t, lod) * uDepth;
    // The penumbra never narrows below two pixels' worth of ray rise: the contact edge stays antialiased.
    float lit = clamp(0.5 + above / (t * 0.09 + 2.0 * rise / uRes.y), 0.0, 1.0);
    shadow = min(shadow, mix(1.0, lit * lit * (3.0 - 2.0 * lit), 1.0 - float(i) / 48.0));
    // Exact early outs: the minimum can only fall, and once the ray clears the tallest possible caster by
    // half a penumbra it stays clear (it climbs faster than the penumbra widens), so every later step is lit.
    if (shadow < 0.002) break;
    if (rise >= 0.045 && h0 + t * rise - top >= 0.5 * (t * 0.09 + 2.0 * rise / uRes.y)) break;
  }

  // Paper in a room is lit twice: by the lamp, and by everything else (walls, ceiling, the sheet itself).
  // The room light fills the shadows, so a recess reads as a soft grey step, never a black hole, and
  // a wall turned to the lamp brightens by a bounded amount instead of glowing (the glow is the bevel look).
  float m = letter(uv);
  float direct = min(diffuse / flat0, 1.7);
  float room = 0.58 * (1.0 - 0.10 * smoothstep(0.2, 0.9, m));
  vec3 base = mix(uPaper, uInk, uInked * smoothstep(0.35, 0.6, m));
  // Pulp settles unevenly: a faint cloud in the sheet's tone. The crushed floor is a touch denser.
  base *= 1.0 + (cloudAt(uv) - 0.5) * 0.05 * uGrain;
  base *= 1.0 - 0.025 * smoothstep(0.6, 0.95, m);
  vec3 color = base * (room + (1.0 - 0.58) * direct * shadow);
  // Gentle falloff across the sheet from the lamp side.
  float falloff = 1.0 - 0.12 * dot(uv - 0.5, -normalize(L.xy + 1e-6));
  color *= falloff;
  outColor = vec4(toSRGB(color) + dither(gl_FragCoord.xy), 1.0);
}`

// One axis of a Gaussian (sigma 1.25 texels). Run twice when the text changes, it turns the 8-bit
// height map into a smooth half-float one: 8-bit levels form one-texel terraces, and a lamp this low
// draws every terrace as a scratch on the walls and a tooth on the shadows.
const SMOOTH_FS = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 outColor;
uniform sampler2D uSource;
uniform vec2 uStep;
void main() {
  float w[5] = float[5](0.3125, 0.2516, 0.1312, 0.0443, 0.0097);
  float sum = texture(uSource, vUv).r * w[0];
  for (int i = 1; i < 5; i++) {
    sum += texture(uSource, vUv + uStep * float(i)).r * w[i];
    sum += texture(uSource, vUv - uStep * float(i)).r * w[i];
  }
  outColor = vec4(sum / 0.9773, 0.0, 0.0, 1.0);
}`

function createRaking(): Material<RakingState> {
  let program: Program
  let smooth: Program
  let half = false
  let vao: WebGLVertexArrayObject | null = null
  let heightTex: WebGLTexture | null = null
  let state: RakingState
  let light = { azimuth: 200, elevation: 16 }
  let size: [number, number] = [0, 0]

  function rebuild(gl: WebGL2RenderingContext, width: number, height: number) {
    const scale = Math.min(1, 1600 / Math.max(width, height))
    const w = Math.max(8, Math.round(width * scale))
    const h = Math.max(8, Math.round(height * scale))
    const canvas = drawHeight(state, w, h)
    const texture = (internal: number, format: number, type: number, data: TexImageSource | null) => {
      const t = gl.createTexture()!
      gl.bindTexture(gl.TEXTURE_2D, t)
      if (data) {
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true)
        gl.texImage2D(gl.TEXTURE_2D, 0, internal, format, type, data)
        gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)
      } else gl.texImage2D(gl.TEXTURE_2D, 0, internal, w, h, 0, format, type, null)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
      return t
    }
    const source = texture(gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE, canvas)
    // Half-float when it can be rendered to; otherwise 8-bit, still smoothed.
    const [internal, format, type] = half ? [gl.R16F, gl.RED, gl.HALF_FLOAT] : [gl.RGBA8, gl.RGBA, gl.UNSIGNED_BYTE]
    const across = texture(internal, format, type, null)
    const result = texture(internal, format, type, null)
    const fbo = gl.createFramebuffer()
    gl.bindFramebuffer(gl.FRAMEBUFFER, fbo)
    gl.viewport(0, 0, w, h)
    smooth.use()
    gl.bindVertexArray(vao)
    gl.activeTexture(gl.TEXTURE0)
    gl.uniform1i(smooth.uniforms.uSource, 0)
    for (const [from, to, step] of [[source, across, [1 / w, 0]], [across, result, [0, 1 / h]]] as const) {
      gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, to, 0)
      gl.bindTexture(gl.TEXTURE_2D, from)
      gl.uniform2f(smooth.uniforms.uStep, step[0], step[1])
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    }
    gl.bindFramebuffer(gl.FRAMEBUFFER, null)
    gl.deleteFramebuffer(fbo)
    gl.deleteTexture(source)
    gl.deleteTexture(across)
    gl.bindTexture(gl.TEXTURE_2D, result)
    gl.generateMipmap(gl.TEXTURE_2D)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR)
    if (heightTex) gl.deleteTexture(heightTex)
    heightTex = result
    size = [width, height]
  }

  const shapeChanged = (a: RakingState, b: RakingState) =>
    a.text !== b.text || a.font !== b.font || a.weight !== b.weight || a.softness !== b.softness

  return {
    programs: [[FULLSCREEN_VS, FS], [FULLSCREEN_VS, SMOOTH_FS]],
    init(stage, props) {
      state = props
      light = { azimuth: props.azimuth, elevation: props.elevation }
      program = createProgram(stage.gl, FULLSCREEN_VS, FS)
      smooth = createProgram(stage.gl, FULLSCREEN_VS, SMOOTH_FS)
      half = !!stage.gl.getExtension("EXT_color_buffer_float")
      vao = stage.gl.createVertexArray()
      rebuild(stage.gl, stage.cssWidth * 2, stage.cssHeight * 2)
    },
    update(stage, props, previous) {
      state = props
      if (props.azimuth !== previous.azimuth || props.elevation !== previous.elevation)
        light = { azimuth: props.azimuth, elevation: props.elevation }
      if (shapeChanged(props, previous)) rebuild(stage.gl, stage.cssWidth * 2, stage.cssHeight * 2)
    },
    resize(stage) {
      const w = stage.cssWidth * 2
      const h = stage.cssHeight * 2
      if (Math.abs(w - size[0]) > 2 || Math.abs(h - size[1]) > 2) rebuild(stage.gl, w, h)
    },
    input(stage) {
      let dragging = false
      let last: [number, number] = [0, 0]
      stage.listen(stage.canvas, "pointerdown", (event) => {
        if (!state.interactive) return
        dragging = true
        last = [event.clientX, event.clientY]
        stage.canvas.setPointerCapture(event.pointerId)
        stage.canvas.style.cursor = "grabbing"
      })
      stage.listen(stage.canvas, "pointermove", (event) => {
        if (!state.interactive) return
        if (!dragging) {
          stage.canvas.style.cursor = "grab"
          return
        }
        const dx = event.clientX - last[0]
        const dy = event.clientY - last[1]
        last = [event.clientX, event.clientY]
        // Horizontal drag walks the lamp around the sheet; vertical raises or lowers it.
        light = {
          azimuth: (light.azimuth + dx * 0.5 + 360) % 360,
          elevation: Math.min(70, Math.max(3, light.elevation - dy * 0.15)),
        }
        stage.invalidate()
      })
      const end = (event: PointerEvent) => {
        dragging = false
        stage.canvas.releasePointerCapture?.(event.pointerId)
      }
      stage.listen(stage.canvas, "pointerup", end)
      stage.listen(stage.canvas, "pointercancel", end)
      stage.listen(stage.canvas.parentElement!, "keydown", (event) => {
        if (!state.interactive) return
        const big = event.shiftKey ? 4 : 1
        if (event.key === "ArrowLeft") light.azimuth = (light.azimuth - 5 * big + 360) % 360
        else if (event.key === "ArrowRight") light.azimuth = (light.azimuth + 5 * big) % 360
        else if (event.key === "ArrowUp") light.elevation = Math.min(70, light.elevation + 2 * big)
        else if (event.key === "ArrowDown") light.elevation = Math.max(3, light.elevation - 2 * big)
        else return
        event.preventDefault()
        stage.invalidate()
      })
    },
    frame(stage) {
      const { gl } = stage
      const az = (light.azimuth * Math.PI) / 180
      const el = (light.elevation * Math.PI) / 180
      gl.viewport(0, 0, stage.width, stage.height)
      program.use()
      const u = program.uniforms
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, heightTex)
      gl.uniform1i(u.uHeight, 0)
      gl.uniform2f(u.uRes, stage.width, stage.height)
      gl.uniform3f(u.uLight, Math.cos(az) * Math.cos(el), Math.sin(az) * Math.cos(el), Math.sin(el))
      gl.uniform1f(u.uDepth, -state.depth * 0.011)
      gl.uniform1f(u.uGrain, state.grain)
      gl.uniform3fv(u.uPaper, linearRGB(state.paper))
      gl.uniform3fv(u.uInk, linearRGB(state.ink))
      gl.uniform1f(u.uInked, state.inked ? 1 : 0)
      gl.bindVertexArray(vao)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
      return false
    },
    dispose(stage) {
      program?.dispose()
      smooth?.dispose()
      if (heightTex) stage.gl.deleteTexture(heightTex)
      if (vao) stage.gl.deleteVertexArray(vao)
      heightTex = null
    },
  }
}

addPropertyControls(RakingLight, {
  text: { type: ControlType.String, title: "Text", defaultValue: rakingDefaults.text },
  font: { type: ControlType.String, title: "Font", defaultValue: rakingDefaults.font },
  weight: { type: ControlType.Number, title: "Weight", min: 100, max: 900, step: 100, defaultValue: rakingDefaults.weight },
  depth: { type: ControlType.Number, title: "Depth", min: 0, max: 1, step: 0.01, defaultValue: rakingDefaults.depth },
  softness: { type: ControlType.Number, title: "Softness", min: 0, max: 1, step: 0.01, defaultValue: rakingDefaults.softness },
  azimuth: { type: ControlType.Number, title: "Lamp angle", min: 0, max: 360, step: 1, unit: "°", defaultValue: rakingDefaults.azimuth },
  elevation: { type: ControlType.Number, title: "Lamp height", min: 3, max: 70, step: 1, unit: "°", defaultValue: rakingDefaults.elevation },
  paper: { type: ControlType.Color, title: "Paper", defaultValue: rakingDefaults.paper },
  inked: { type: ControlType.Boolean, title: "Inked", defaultValue: rakingDefaults.inked },
  ink: { type: ControlType.Color, title: "Ink", defaultValue: rakingDefaults.ink, hidden: (p: RakingProps) => !p.inked },
  grain: { type: ControlType.Number, title: "Grain", min: 0, max: 1, step: 0.01, defaultValue: rakingDefaults.grain },
  interactive: { type: ControlType.Boolean, title: "Movable lamp", defaultValue: rakingDefaults.interactive },
  maxDpr: { type: ControlType.Number, title: "Max DPR", min: 1, max: 3, step: 0.25, defaultValue: rakingDefaults.maxDpr },
})

